      "assets/style.css": "/* The template's stylesheet: tooling, kept current by unify update. Its look is\n   the custom properties set in :root below, and the site's own values for them\n   live in theme.css beside this file — a file unify update never overwrites,\n   named under keep: in unify.yaml's template: block. The import puts it in the\n   theme layer, which wins over the base layer whatever the order, so a value\n   set there wins and a property left out keeps its default here. */\n@layer base, theme;\n@import url(\"theme.css\") layer(theme);\n\n@layer base {\n  :root {\n    color-scheme: light dark;\n    --font-body: 100%/1.5 system-ui, sans-serif;\n    --color-text: canvastext;\n    --color-background: canvas;\n    --color-link: linktext;\n    --color-rule: #88888880;\n    --measure: 42rem;\n    --space: 1.5rem;\n  }\n\n  body {\n    max-width: var(--measure);\n    margin: 0 auto;\n    padding: var(--space);\n    font: var(--font-body);\n    color: var(--color-text);\n    background: var(--color-background);\n  }\n\n  a {\n    color: var(--color-link);\n  }\n\n  nav a {\n    margin-right: 1rem;\n  }\n\n  .site-footer {\n    margin-top: 3rem;\n    padding-top: 1rem;\n    border-top: 1px solid var(--color-rule);\n    font-size: 0.875rem;\n  }\n\n  /* Scaffolded copy nobody should publish: conspicuous on purpose, so a\n     reader cannot mistake an invented name, date, price, or address for a\n     fact. Delete the class along with the text it marks. */\n  .placeholder {\n    border: 1px dashed;\n    border-radius: 0.25em;\n    padding: 0 0.25em;\n    font-style: italic;\n    opacity: 0.8;\n  }\n\n  /* Design-time preview only — built pages contain no <slot> elements. */\n  slot {\n    display: contents;\n  }\n}\n",
